selector_to_html = {"a[href=\"../../example/Cpp.html#cpp-slam\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">6.2.24 </span>Slam<a class=\"headerlink\" href=\"#cpp-slam\" title=\"Link to this heading\">\uf0c1</a></h2><p>In this example, <strong>slam</strong> is used to send messages to the mapping service via this node to achieve mapping functionality.</p>", "a[href=\"../../example/Python.html#py-get-map\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">6.1.28 </span>Retrieve a Stored Map<a class=\"headerlink\" href=\"#py-get-map\" title=\"Link to this heading\">\uf0c1</a></h2><p>In this example, <code class=\"docutils literal notranslate\"><span class=\"pre\">get_map</span></code> is used to retrieve stored map data by name, including the map path, resolution, dimensions, and map ID.</p>", "a[href=\"#map-params-lookup\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Obtaining Map Identifiers and Coordinates<a class=\"headerlink\" href=\"#map-params-lookup\" title=\"Link to this heading\">\uf0c1</a></h2><p>Parameters commonly needed when calling the map-retrieval, relocalization, and navigation interfaces can be obtained as follows:</p>", "a[href=\"../../example/Python.html#py-relocate\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">6.1.27 </span>Relocate<a class=\"headerlink\" href=\"#py-relocate\" title=\"Link to this heading\">\uf0c1</a></h2><p>This example uses the map built in the <a class=\"reference internal\" href=\"#py-slam\">Map Building</a> step for localization.</p>", "a[href=\"#id2\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Map Retrieval<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">\uf0c1</a></h2>", "a[href=\"../../example/Cpp.html#cpp-get-map\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">6.2.26 </span>Retrieve a Stored Map<a class=\"headerlink\" href=\"#cpp-get-map\" title=\"Link to this heading\">\uf0c1</a></h2><p>In this example, <code class=\"docutils literal notranslate\"><span class=\"pre\">get_map</span></code> is used to retrieve stored map data by name, including the map path, resolution, dimensions, and map ID.</p>", "a[href=\"#id1\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Map Building<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">\uf0c1</a></h2><p>Use topics to control the start and stop of the mapping process and specify the name under which the map is saved.</p>", "a[href=\"../../example/Python.html#py-slam\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">6.1.26 </span>Slam<a class=\"headerlink\" href=\"#py-slam\" title=\"Link to this heading\">\uf0c1</a></h2><p>In this example, <strong>slam</strong> is used to send messages to the mapping service via this node to achieve mapping functionality.</p>", "a[href=\"#slam\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">5.5.2 </span>SLAM (Optional)<a class=\"headerlink\" href=\"#slam\" title=\"Link to this heading\">\uf0c1</a></h1><p><strong>The SLAM (Simultaneous Localization and Mapping) module provides interfaces for map building, map retrieval, and relocalization, enabling the robot to create maps in unknown environments and accurately localize itself using existing maps.</strong></p>", "a[href=\"#id3\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Relocalization<a class=\"headerlink\" href=\"#id3\" title=\"Link to this heading\">\uf0c1</a></h2><p>To localize the robot to a specified position within an existing map, first trigger the relocalization command, then provide an initial pose estimate, and finally confirm success by subscribing to the localization result topic.</p>", "a[href=\"#id4\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Programming Examples<a class=\"headerlink\" href=\"#id4\" title=\"Link to this heading\">\uf0c1</a></h2><p>For detailed programming examples and code descriptions, see:</p>", "a[href=\"../../example/Cpp.html#cpp-relocate\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">6.2.25 </span>Relocate<a class=\"headerlink\" href=\"#cpp-relocate\" title=\"Link to this heading\">\uf0c1</a></h2><p>This example uses the map built in the <a class=\"reference internal\" href=\"#cpp-slam\">Map Building</a> step for localization.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false, theme: 'material', duration: [300, 200], delay: [200, 100],

            });
        };
    };
    console.log("tippy tips loaded!");
};
